import XCTest
import AppKit
import Markdown
@testable import Zerus_Native

@MainActor final class MacClipboardTests: XCTestCase {
    // A complete PNG from an independent fixture; never generated by the importer.
    private let png = Data(base64Encoded: "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=")!
    func testListOwnedCardsCrossClipboardAsItemsOrStandaloneCardsWithoutAssets() async throws {
        let defaults = UserDefaults.standard, key = "zerus.mac.codeBlocks", previous = defaults.object(forKey: key)
        defer { if let previous { defaults.set(previous, forKey: key) } else { defaults.removeObject(forKey: key) } }
        func structure(_ source: String) -> (owners: [Int?], depths: [Int], items: Int, oldOwners: [Int?], oldDepths: [Int]) {
            var owners: [Int?] = [], depths: [Int] = [], items = 0, oldOwners: [Int?] = [], oldDepths: [Int] = []
            func collect(_ node: any Markup, owner: Int? = nil, depth: Int = 0) {
                var owner = owner; let depth = depth + (node is BlockQuote ? 1 : 0)
                if node is ListItem { owner = items; items += 1 }
                if node is CodeBlock || node is Markdown.Table || node is ThematicBreak { owners.append(owner); depths.append(depth) }
                if (node as? Markdown.Text)?.string.contains("old") == true { oldOwners.append(owner); oldDepths.append(depth) }
                for child in node.children { collect(child, owner: owner, depth: depth) }
            }
            collect(Document(parsing: source)); return (owners, depths, items, oldOwners, oldDepths)
        }
        try await systemClipboard { board in
            for table in [false, true] { for quoted in [false, true] { for nested in [false, true] { for marker in ["- ", "10. "] { for ending in ["\n", "\r\n", "\r"] {
                defaults.set(true, forKey: key)
                let outer = quoted ? "> " : "", inner = quoted ? "> " : "", depth = nested ? (quoted ? 2 : 1) : (quoted ? 2 : 0)
                let owner = nested ? 1 : 0
                let padding = String(repeating: " ", count: marker.utf16.count)
                let body = table ? "| A |\n| --- |\n| old |" : "```swift\nold\n```"
                let header = nested ? outer + marker + "Root" + ending + outer + padding + "> - Parent" + ending : outer + marker + "Parent" + ending
                let source = header + body.components(separatedBy: "\n").map { (nested ? outer + padding + ">   " : outer + padding + inner) + $0 }.joined(separator: ending) + ending
                for wholeItem in [true, false] {
                    var fragment: NativeClipboardFragment?, html: Data?
                    try await self.editor(source, root: true) { view, coordinator, state, root in
                        let old = (view.string as NSString).range(of: "old")
                        guard old.location != NSNotFound else { XCTFail("The copied list card must remain visible"); return }
                        var selected = NSRange(location: 0, length: view.string.utf16.count)
                        if !wholeItem { _ = view.attributedString().attribute(table ? .macTable : .macCode, at: old.location, longestEffectiveRange: &selected, in: selected) }
                        view.setSelectedRange(selected); try await coordinator.copy(cut: true)
                        fragment = try NativeClipboardFragment.decode(try XCTUnwrap(board.data(forType: .init(NativeClipboardFragment.type))))
                        html = board.data(forType: .html); XCTAssertNotNil(html, "Native cards must export semantic HTML")
                        let bare = body.components(separatedBy: "\n").map { String(repeating: "> ", count: depth) + $0 }.joined(separator: ending) + (table ? "" : ending)
                        XCTAssertEqual(fragment?.markdown, wholeItem ? source : bare)
                        XCTAssertEqual(structure(try XCTUnwrap(fragment).markdown).owners, wholeItem ? [owner] : [nil])
                        XCTAssertEqual(structure(try XCTUnwrap(fragment).markdown).depths, [depth]); XCTAssertTrue(try XCTUnwrap(fragment).resources.isEmpty)
                        XCTAssertEqual(state.text, wholeItem ? "" : header)
                        coordinator.action("undo"); XCTAssertEqual(state.text, source); XCTAssertEqual(view.selectedRange(), selected)
                        XCTAssertEqual(MacMarkdown.markdown(view.attributedString()), source)
                        coordinator.action("redo"); XCTAssertEqual(state.text, wholeItem ? "" : header)
                        XCTAssertFalse(FileManager.default.fileExists(atPath: try XCTUnwrap(root).appendingPathComponent("assets").path))
                    }
                    for format in html == nil ? ["fragment"] : ["fragment", "html"] {
                        try await self.editor("", root: true) { view, coordinator, state, root in
                            try await coordinator.paste(format == "fragment" ? .fragment(try XCTUnwrap(fragment)) : .html(try XCTUnwrap(html)))
                            XCTAssertEqual(structure(state.text).owners, wholeItem ? [owner] : [nil]); XCTAssertEqual(structure(state.text).depths, [depth])
                            XCTAssertTrue(view.string.contains("old"))
                            XCTAssertFalse(state.source, "Mapped copied items and standalone cards must retain rich editing")
                            let saved = state.text
                            coordinator.action("undo"); XCTAssertEqual(state.text, "")
                            coordinator.action("redo"); XCTAssertEqual(state.text, saved)
                            XCTAssertFalse(FileManager.default.fileExists(atPath: try XCTUnwrap(root).appendingPathComponent("assets").path))
                        }
                    }
                    if !table, wholeItem {
                        defaults.set(false, forKey: key)
                        for format in html == nil ? ["fragment"] : ["fragment", "html"] {
                            try await self.editor("", root: true) { view, coordinator, state, root in
                                try await coordinator.paste(format == "fragment" ? .fragment(try XCTUnwrap(fragment)) : .html(try XCTUnwrap(html)))
                                XCTAssertEqual(structure(state.text).items, nested ? 2 : 1, "Creation-off conversion must retain the selected item")
                                XCTAssertTrue(structure(state.text).owners.isEmpty); XCTAssertTrue(view.string.contains("Parent")); XCTAssertTrue(view.string.contains("old"))
                                XCTAssertEqual(structure(state.text).oldOwners, [owner]); XCTAssertEqual(structure(state.text).oldDepths, [depth])
                                XCTAssertFalse(FileManager.default.fileExists(atPath: try XCTUnwrap(root).appendingPathComponent("assets").path))
                            }
                        }
                        defaults.set(true, forKey: key)
                    }
                }
            } } } } }
        }
        try await systemClipboard { board in
            for quotes in ["", "> "] { for ending in ["\n", "\r\n"] { for wholeItem in [false, true] {
                let header = quotes + "- Parent" + ending
                let source = header + quotes + "  ***" + ending
                var fragment: NativeClipboardFragment?, html: Data?
                try await self.editor(source, root: true) { view, coordinator, state, root in
                    let raw = view.string as NSString
                    let glyph = raw.range(of: "\u{FFFC}")
                    guard glyph.location != NSNotFound else { XCTFail("The selected rule must be visible"); return }
                    let selected = wholeItem ? NSRange(location: 0, length: raw.length) : raw.paragraphRange(for: glyph)
                    view.setSelectedRange(selected); try await coordinator.copy(cut: true)
                    fragment = try NativeClipboardFragment.decode(try XCTUnwrap(board.data(forType: .init(NativeClipboardFragment.type))))
                    html = board.data(forType: .html)
                    XCTAssertEqual(fragment?.markdown, wholeItem ? source : quotes + "***" + ending)
                    XCTAssertEqual(structure(try XCTUnwrap(fragment).markdown).owners, wholeItem ? [0] : [nil])
                    XCTAssertEqual(structure(try XCTUnwrap(fragment).markdown).depths, [quotes.isEmpty ? 0 : 1])
                    XCTAssertTrue(try XCTUnwrap(fragment).resources.isEmpty)
                    XCTAssertEqual(state.text, wholeItem ? "" : header)
                    coordinator.action("undo"); XCTAssertEqual(state.text, source); XCTAssertEqual(view.selectedRange(), selected)
                    coordinator.action("redo"); XCTAssertEqual(state.text, wholeItem ? "" : header)
                    XCTAssertFalse(FileManager.default.fileExists(atPath: try XCTUnwrap(root).appendingPathComponent("assets").path))
                }
                for format in ["fragment", "html"] {
                    try await self.editor("", root: true) { view, coordinator, state, root in
                        try await coordinator.paste(format == "fragment" ? .fragment(try XCTUnwrap(fragment)) : .html(try XCTUnwrap(html)))
                        XCTAssertEqual(structure(state.text).owners, wholeItem ? [0] : [nil])
                        XCTAssertEqual(structure(state.text).depths, [quotes.isEmpty ? 0 : 1])
                        XCTAssertFalse(state.source); XCTAssertTrue(view.string.contains("\u{FFFC}"))
                        let saved = state.text
                        coordinator.action("undo"); XCTAssertEqual(state.text, "")
                        coordinator.action("redo"); XCTAssertEqual(state.text, saved)
                        XCTAssertFalse(FileManager.default.fileExists(atPath: try XCTUnwrap(root).appendingPathComponent("assets").path))
                    }
                }
            } } }
        }
        defaults.set(false, forKey: key)
        for (markdown, expected, visible) in [("-     [x] old\n", "- \\[x\\] old\n\n", "• [x] old"), ("- ```\n  ```\n", "- \u{200b}\n\n", "• ")] {
            try await editor("", root: true) { view, coordinator, state, _ in
                try await coordinator.paste(.fragment(.init(markdown: markdown)))
                XCTAssertEqual(state.text, expected)
                XCTAssertTrue(view.string.hasPrefix(visible)); XCTAssertEqual(structure(state.text).items, 1)
            }
        }
    }
    func testQuotedCardsCrossTheClipboardWithoutFlatteningOrCreatingAssets() async throws {
        let defaults = UserDefaults.standard, key = "zerus.mac.codeBlocks", previous = defaults.object(forKey: key)
        defer { if let previous { defaults.set(previous, forKey: key) } else { defaults.removeObject(forKey: key) } }
        defaults.set(true, forKey: key)
        func depth(_ node: any Markup, quote: Int = 0) -> [Int] {
            let quote = quote + (node is BlockQuote ? 1 : 0)
            if node is CodeBlock || node is Markdown.Table { return [quote] }
            return node.children.flatMap { depth($0, quote: quote) }
        }
        try await systemClipboard { board in
            for table in [false, true] { for ending in ["\n", "\r\n", "\r"] {
                let source = (table ? "> > | A | B |\n> > | --- | --- |\n> > | One | Two |\n" : "> > ```swift\n> > let value = 1\n> > ```\n").replacingOccurrences(of: "\n", with: ending)
                var fragment: NativeClipboardFragment?, html: Data?
                try await self.editor(source, root: true) { view, coordinator, state, root in
                    let all = NSRange(location: 0, length: view.string.utf16.count)
                    view.setSelectedRange(all); try await coordinator.copy(cut: true)
                    fragment = try NativeClipboardFragment.decode(try XCTUnwrap(board.data(forType: .init(NativeClipboardFragment.type))))
                    XCTAssertEqual(fragment?.markdown, table ? String(source.dropLast()) : source)
                    html = try XCTUnwrap(board.data(forType: .html))
                    XCTAssertEqual(depth(Document(parsing: try XCTUnwrap(fragment).markdown)), [2])
                    XCTAssertEqual(state.text, "")
                    coordinator.action("undo"); XCTAssertEqual(state.text, source); XCTAssertEqual(view.selectedRange(), all)
                    coordinator.action("redo"); XCTAssertEqual(state.text, "")
                    XCTAssertFalse(FileManager.default.fileExists(atPath: try XCTUnwrap(root).appendingPathComponent("assets").path))
                }
                for format in ["fragment", "html"] {
                    try await self.editor("", root: true) { view, coordinator, state, root in
                        try await coordinator.paste(format == "fragment" ? .fragment(try XCTUnwrap(fragment)) : .html(try XCTUnwrap(html)))
                        XCTAssertFalse(state.source); XCTAssertEqual(depth(Document(parsing: state.text)), [2])
                        if table {
                            let cell = try XCTUnwrap(MacRichTable.at(view.attributedString(), 0))
                            XCTAssertEqual(cell.table.original.rows, [["A", "B"], ["One", "Two"]])
                        } else {
                            var bodies: [String] = []
                            func collect(_ node: any Markup) { if let code = node as? CodeBlock { bodies.append(code.code) }; for child in node.children { collect(child) } }
                            collect(Document(parsing: state.text)); XCTAssertEqual(bodies, ["let value = 1\n"])
                        }
                        let saved = state.text
                        coordinator.action("undo"); XCTAssertEqual(state.text, "")
                        coordinator.action("redo"); XCTAssertEqual(state.text, saved)
                        XCTAssertFalse(FileManager.default.fileExists(atPath: try XCTUnwrap(root).appendingPathComponent("assets").path))
                    }
                }
            } }
        }
        defaults.set(false, forKey: key)
        try await editor("", root: true) { _, coordinator, state, _ in
            try await coordinator.paste(.html(Data("<blockquote><pre><code>let value = 1</code></pre></blockquote>".utf8)))
            XCTAssertEqual(depth(Document(parsing: state.text)), [])
            XCTAssertTrue(state.text.hasPrefix("> ")); XCTAssertTrue(state.text.contains("let value")); XCTAssertFalse(state.source)
        }
    }
    func testHorizontalRuleClipboardPreservesSemanticHTMLWithoutCreatingAssets() async throws {
        try await systemClipboard { board in
            let source = "# Before\n---\nAfter\n"
            try await self.editor(source, root: true) { view, coordinator, state, root in
                let selected = (view.string as NSString).range(of: "\u{FFFC}")
                guard selected.location != NSNotFound else { XCTFail("The rule must be a native block before copying"); return }
                view.setSelectedRange(selected); try await coordinator.copy(cut: true)
                let fragment = try NativeClipboardFragment.decode(try XCTUnwrap(board.data(forType: .init(NativeClipboardFragment.type))))
                XCTAssertEqual(fragment.markdown, "---"); XCTAssertTrue(fragment.resources.isEmpty)
                let html = try XCTUnwrap(board.data(forType: .html))
                let converted = try await NativeHTMLClipboard.fragment(html)
                XCTAssertEqual(converted.markdown, "---\n"); XCTAssertTrue(converted.resources.isEmpty)
                XCTAssertEqual(state.text, "# Before\n\nAfter\n")
                coordinator.action("undo"); XCTAssertEqual(state.text, source); XCTAssertEqual(view.selectedRange(), selected)
                XCTAssertFalse(FileManager.default.fileExists(atPath: try XCTUnwrap(root).appendingPathComponent("assets").path))
            }
        }
        for format in ["fragment", "html"] { for ending in ["\n", "\r\n", "\r"] {
            try await self.editor("- abcd\n  - Child\n- Sibling\n".replacingOccurrences(of: "\n", with: ending), root: true) { view, coordinator, state, root in
                let body = (view.string as NSString).range(of: "abcd"), selected = NSRange(location: body.location + 2, length: 0)
                view.setSelectedRange(selected)
                try await coordinator.paste(format == "html" ? .html(Data("<hr>".utf8)) : .fragment(.init(markdown: "---\n")))
                let expected = "- ab\n\n---\n\ncd\n\n- Child\n- Sibling\n".replacingOccurrences(of: "\n", with: ending)
                XCTAssertEqual(state.text, expected); XCTAssertFalse(state.source)
                let parsed = Document(parsing: state.text)
                XCTAssertTrue(parsed.children.contains { $0 is ThematicBreak })
                coordinator.action("undo"); XCTAssertEqual(state.text, "- abcd\n  - Child\n- Sibling\n".replacingOccurrences(of: "\n", with: ending)); XCTAssertEqual(view.selectedRange(), selected)
                coordinator.action("redo"); XCTAssertEqual(state.text, expected)
                view.insertText("New", replacementRange: view.selectedRange())
                XCTAssertEqual(state.text, "- ab\n\n---\nNew\n\ncd\n\n- Child\n- Sibling\n".replacingOccurrences(of: "\n", with: ending))
                XCTAssertFalse(FileManager.default.fileExists(atPath: try XCTUnwrap(root).appendingPathComponent("assets").path))
            }
        } }
    }
    func testCutExportsOnlySelectedTextAndPreservesRemainingBlockRolesAndOwners() async throws {
        try await systemClipboard { board in
            // Clipboard deletion bypasses the keyboard body-clear delegate.
            // Keep the original exported fragment while retaining its empty role.
            for (body, empty, copied, role, headings, quotes, items) in [
                ("# Cut", "# ", "# Cut", "# ", [1], 0, 0),
                ("> Cut", "> ", "> Cut", "> ", [], 1, 0),
                ("> ## Cut", "> ## ", "> ## Cut", "## ", [2], 1, 0),
                ("- ## Cut", "- ## ", "## Cut", "## ", [2], 0, 1),
                ("- > Cut", "- > ", "Cut", "> ", [], 1, 1),
                ("> - ## Cut", "> - ## ", "## Cut", "## ", [2], 1, 1),
                ("Before\n\n## Cut", "Before\n\n## ", "## Cut", "## ", [2], 0, 0),
                ("Before\n\n> Cut", "Before\n\n> ", "> Cut", "> ", [], 1, 0),
                ("- Parent\n\n  ## Cut", "- Parent\n\n  ## ", "## Cut", "## ", [2], 0, 1),
                ("- Parent\n\n  > Cut", "- Parent\n\n  > ", "Cut", "> ", [], 1, 1),
                ("- ## Head\n\n  Cut", "- ## Head\n\n  \u{200b}", "Cut", "", [2], 0, 1)
            ] { for terminated in [false, true] { for ending in (body.contains("\n") || terminated ? ["\n", "\r\n", "\r"] : ["\n"]) {
                let source = body.replacingOccurrences(of: "\n", with: ending) + (terminated ? ending : "")
                let expected = empty.replacingOccurrences(of: "\n", with: ending) + (terminated ? ending : "")
                let refill = source.replacingOccurrences(of: "Cut", with: "New")
                let header = "---\ncustom: keep # comment\n---\n"
                try await self.editor(source, root: false, header: header) { view, coordinator, state, _ in
                    let selection = (view.string as NSString).range(of: "Cut")
                    guard selection.location != NSNotFound else { XCTFail("Missing Cut body"); return }
                    view.setSelectedRange(selection); try await coordinator.copy(cut: true)
                    let fragment = try NativeClipboardFragment.decode(try XCTUnwrap(board.data(forType: .init(NativeClipboardFragment.type))))
                    XCTAssertEqual(fragment.markdown, copied); XCTAssertEqual(board.string(forType: .string), copied)
                    XCTAssertTrue(fragment.resources.isEmpty)
                    XCTAssertEqual(state.text, expected, source); XCTAssertEqual(MacMarkdown.markdown(view.attributedString()), expected)
                    XCTAssertEqual(state.document.content, header + expected)
                    var actualHeadings: [Int] = [], actualQuotes = 0, actualItems = 0, plainInsideItem = 0
                    func walk(_ node: any Markup, inItem: Bool = false) {
                        if let heading = node as? Heading { actualHeadings.append(heading.level) }
                        if node is BlockQuote { actualQuotes += 1 }
                        if node is ListItem { actualItems += 1 }
                        if node is Paragraph, inItem { plainInsideItem += 1 }
                        for child in node.children { walk(child, inItem: inItem || node is ListItem) }
                    }
                    walk(Document(parsing: state.text))
                    XCTAssertEqual(actualHeadings, headings); XCTAssertEqual(actualQuotes, quotes); XCTAssertEqual(actualItems, items)
                    if body.hasPrefix("- ## Head") { XCTAssertEqual(plainInsideItem, 1, "The cleared explicit paragraph must survive parsing") }
                    let caret = view.selectedRange(); XCTAssertEqual(caret, NSRange(location: selection.location, length: 0))
                    XCTAssertEqual((view.typingAttributes[.font] as? NSFont)?.pointSize, MacMarkdown.font(role).pointSize)
                    XCTAssertEqual(view.undoManager?.undoActionName, "Cut")
                    coordinator.action("undo"); XCTAssertEqual(state.text, source); XCTAssertEqual(view.selectedRange(), selection)
                    coordinator.action("redo"); XCTAssertEqual(state.text, expected); XCTAssertEqual(view.selectedRange(), caret)
                    view.insertText("New", replacementRange: caret)
                    XCTAssertEqual(state.text, refill); XCTAssertEqual(state.document.content, header + refill)
                    coordinator.action("undo"); XCTAssertEqual(state.text, expected)
                    coordinator.load(expected, source: false)
                    let end = view.string.utf16.count - (view.string.hasSuffix("\n") ? 1 : 0)
                    view.setSelectedRange(NSRange(location: max(0, end), length: 0))
                    XCTAssertEqual((view.typingAttributes[.font] as? NSFont)?.pointSize, MacMarkdown.font(role).pointSize, "Reopening retains the caret role")
                    view.insertText("New", replacementRange: view.selectedRange())
                    XCTAssertEqual(state.text, refill, "Reopening the cleared block retains its role and ending")
                    if body == "- Parent\n\n  ## Cut", !terminated, ending == "\n" {
                        coordinator.action("undo"); XCTAssertEqual(state.text, expected)
                        coordinator.action("bold")
                        view.insertText("New", replacementRange: view.selectedRange())
                        XCTAssertEqual(state.text, "- Parent\n\n  ## **New**", "An explicit Bold choice in the empty heading must remain active")
                    }
                }
            } } }
            // A mixed Cut must remove selected descendants while retaining
            // the receiving inner block, its item and the untouched sibling.
            for (source, empty, partial, copied) in [
                ("- ## Heading\n  - Child\n    - Grandchild\n\n  Tail\n- Sib\n", "- ## \n- Sib\n", "- ## He\n- Sib\n", "## Heading\n\n- Child\n  - Grandchild\n\nTail"),
                ("- Root\n  - ### Heading\n    - Child\n\n    Tail\n- Sib\n", "- Root\n  - ### \n- Sib\n", "- Root\n  - ### He\n- Sib\n", "### Heading\n\n- Child\n\nTail"),
                ("10. ## Heading\n    8. Child\n\n    Tail\n11. Sib\n", "10. ## \n11. Sib\n", "10. ## He\n11. Sib\n", "## Heading\n\n8. Child\n\nTail"),
                ("- Parent\n\n  ## Heading\n  - Child\n\n  Tail\n- Sib\n", "- Parent\n\n  ## \n- Sib\n", "- Parent\n\n  ## He\n- Sib\n", "## Heading\n\n- Child\n\nTail")
            ] { for ending in ["\n", "\r\n", "\r"] { for offset in [0, 2] {
                let source = source.replacingOccurrences(of: "\n", with: ending)
                let expected = (offset == 0 ? empty : partial).replacingOccurrences(of: "\n", with: ending)
                let copied = (offset == 0 ? copied : copied.replacingOccurrences(of: "### Heading", with: "ading").replacingOccurrences(of: "## Heading", with: "ading")).replacingOccurrences(of: "\n", with: ending)
                try await self.editor(source, root: true) { view, coordinator, state, _ in
                    let raw = view.string as NSString, first = raw.range(of: "Heading"), last = raw.range(of: "Tail")
                    guard first.location != NSNotFound, last.location != NSNotFound else { XCTFail("Missing inner Cut endpoints"); return }
                    let selected = NSRange(location: first.location + offset, length: NSMaxRange(last) - first.location - offset)
                    view.setSelectedRange(selected)
                    try await coordinator.copy(cut: true)
                    let fragment = try NativeClipboardFragment.decode(try XCTUnwrap(board.data(forType: .init(NativeClipboardFragment.type))))
                    XCTAssertEqual(fragment.markdown, copied, source)
                    XCTAssertEqual(state.text, expected, source)
                    XCTAssertEqual(MacMarkdown.markdown(view.attributedString()), expected)
                    var parents: [Int?] = [], levels: [Int] = [], headingOwners: [Int?] = []
                    func walk(_ node: any Markup, parent: Int? = nil) {
                        var owner = parent
                        if node is ListItem { owner = parents.count; parents.append(parent) }
                        if let heading = node as? Heading { levels.append(heading.level); headingOwners.append(owner) }
                        for child in node.children { walk(child, parent: owner) }
                    }
                    walk(Document(parsing: state.text))
                    XCTAssertEqual(parents, source.contains("Root") ? [nil, 0, nil] : [nil, nil])
                    XCTAssertEqual(levels, [source.contains("###") ? 3 : 2])
                    XCTAssertEqual(headingOwners, [source.contains("Root") ? 1 : 0])
                    let caret = NSRange(location: selected.location, length: 0)
                    XCTAssertEqual(view.selectedRange(), caret); XCTAssertEqual(view.undoManager?.undoActionName, "Cut")
                    coordinator.action("undo"); XCTAssertEqual(state.text, source); XCTAssertEqual(view.selectedRange(), selected)
                    coordinator.action("redo"); XCTAssertEqual(state.text, expected); XCTAssertEqual(view.selectedRange(), caret)
                    view.insertText("New", replacementRange: caret)
                    let typed = expected.replacingOccurrences(of: offset == 0 ? "## " + ending : "## He", with: offset == 0 ? "## New" + ending : "## HeNew")
                    XCTAssertEqual(state.text, typed)
                    coordinator.action("undo"); XCTAssertEqual(state.text, expected)
                    coordinator.load(expected, source: false)
                    view.setSelectedRange(caret); view.insertText("New", replacementRange: caret)
                    XCTAssertEqual(state.text, typed, "Reopening the cut inner block must retain its role")
                }
            } } }
            for outgoing in [false, true] { for ending in ["\n", "\r\n", "\r"] { for table in [false, true] {
                let card = table ? "  | A | B |\n  | :---: | ---: |\n  | abcdef | Keep |\n" : "  ```swift\n  abcdef\n  ```\n"
                let source = ("- Parent\n" + card + "- Sibling\n").replacingOccurrences(of: "\n", with: ending)
                let expected = (outgoing ? "- Parent\n  ```swift\n  abcling\n  ```\n" : "- Par\n  ```swift\n  def\n  ```\n- Sibling\n").replacingOccurrences(of: "\n", with: ending)
                try await self.editor(source, root: true) { view, coordinator, state, _ in
                    let raw = view.string as NSString, first = raw.range(of: outgoing ? "abcdef" : "Parent"), last = raw.range(of: outgoing ? "Sibling" : "abcdef")
                    let selected = NSRange(location: first.location + 3, length: last.location - first.location)
                    view.setSelectedRange(selected); try await coordinator.copy(cut: true)
                    let fragment = try NativeClipboardFragment.decode(try XCTUnwrap(board.data(forType: .init(NativeClipboardFragment.type))))
                    var bodies: [String] = [], text: [String] = []
                    func collect(_ node: any Markup) {
                        if let code = node as? CodeBlock { bodies.append(code.code) }
                        if let value = node as? Markdown.Text { text.append(value.string) }
                        for child in node.children { collect(child) }
                    }
                    collect(Document(parsing: fragment.markdown))
                    XCTAssertEqual(bodies, table ? [] : [outgoing ? "def\n" : "abc\n"])
                    XCTAssertEqual(text, table ? (outgoing ? ["def", "Keep", "Sib"] : ["ent", "A", "B", "abc"]) : [outgoing ? "Sib" : "ent"])
                    XCTAssertTrue(fragment.resources.isEmpty)
                    if table {
