                ("10. ## Heading\n    8. Child\n\n    Tail\n11. Sib\n", "## Heading\n\n8. Child\n\nTail", "ading\n\n8. Child\n\nTail", "10. ## Heading\n    8. Child\n\n    Tail"),
                ("- ## Heading\n  - ### Child\n    - Grandchild\n\n  Tail\n- Sib\n", "## Heading\n\n- ### Child\n  - Grandchild\n\nTail", "ading\n\n- ### Child\n  - Grandchild\n\nTail", "- ## Heading\n  - ### Child\n    - Grandchild\n\n  Tail")
            ] { for ending in ["\n", "\r\n", "\r"] { for mode in ["body", "partial", "item"] {
                let source = source.replacingOccurrences(of: "\n", with: ending)
                let expected = (mode == "body" ? body : mode == "partial" ? partial : whole).replacingOccurrences(of: "\n", with: ending)
                func shape(_ source: String) -> [String] {
                    var result: [String] = [], next = 0
                    func walk(_ node: any Markup, owner: Int? = nil) {
                        var owner = owner
                        if let list = node as? OrderedList { result.append("ol:\(list.startIndex)") }
                        if node is UnorderedList { result.append("ul") }
                        if node is ListItem { let index = next; next += 1; result.append("item:\(index):\(owner.map(String.init) ?? "root")"); owner = index }
                        if let heading = node as? Heading { result.append("h\(heading.level):\(owner.map(String.init) ?? "root"):\(heading.plainText)") }
                        if let paragraph = node as? Paragraph { result.append("p:\(owner.map(String.init) ?? "root"):\(paragraph.plainText)") }
                        for child in node.children { walk(child, owner: owner) }
                    }
                    walk(Document(parsing: source)); return result
                }
                var copied: NativeClipboardFragment?, html: Data?
                try await self.editor(source, root: true) { view, coordinator, state, _ in
                    let raw = view.string as NSString, first = raw.range(of: "Heading"), last = raw.range(of: "Tail")
                    guard first.location != NSNotFound, last.location != NSNotFound else { XCTFail("Missing mixed copy endpoints"); return }
                    let start = mode == "item" ? raw.paragraphRange(for: first).location : first.location + (mode == "partial" ? 2 : 0)
                    let selection = NSRange(location: start, length: NSMaxRange(last) - start)
                    view.setSelectedRange(selection); try await coordinator.copy(cut: false)
                    let fragment = try NativeClipboardFragment.decode(try XCTUnwrap(board.data(forType: .init(NativeClipboardFragment.type))))
                    XCTAssertEqual(fragment.markdown, expected); XCTAssertEqual(shape(fragment.markdown), shape(expected))
                    XCTAssertEqual(state.text, source); XCTAssertEqual(MacMarkdown.markdown(view.attributedString()), source); XCTAssertEqual(view.selectedRange(), selection)
                    XCTAssertFalse(view.undoManager?.canUndo == true)
                    copied = fragment; html = board.data(forType: .html)
                    if shape(expected).contains(where: { $0.hasPrefix("h") }) { XCTAssertNotNil(html, "Selected headings need semantic HTML even when their native row begins with a list marker") }
                }
                for native in html == nil ? [true] : [true, false] {
                    try await self.editor("", root: true) { view, coordinator, state, _ in
                        try await coordinator.paste(native ? .fragment(try XCTUnwrap(copied)) : .html(try XCTUnwrap(html)))
                        XCTAssertEqual(shape(state.text), shape(expected))
                        let saved = state.text
                        coordinator.action("undo"); XCTAssertEqual(state.text, "")
                        coordinator.action("redo"); XCTAssertEqual(state.text, saved)
                        let text = mode == "partial" ? "ading" : "Heading", word = (view.string as NSString).range(of: mode == "partial" ? "ading" : "Heading")
                        guard word.location != NSNotFound else { XCTFail("Copied heading body must remain editable"); return }
                        view.setSelectedRange(NSRange(location: NSMaxRange(word), length: 0)); view.insertText("!", replacementRange: view.selectedRange())
                        XCTAssertEqual(shape(state.text), shape(expected.replacingOccurrences(of: text, with: text + "!")))
                        XCTAssertEqual(MacMarkdown.markdown(MacMarkdown.render(state.text)), state.text)
                    }
                }
            } } }
            for source in ["Intro\n- a\n", "> Intro\n> - a\n"] {
                try await self.editor(source, root: true) { view, coordinator, state, _ in
                    view.setSelectedRange(NSRange(location: 0, length: view.string.utf16.count)); try await coordinator.copy(cut: false)
                    let fragment = try NativeClipboardFragment.decode(try XCTUnwrap(board.data(forType: .init(NativeClipboardFragment.type))))
                    XCTAssertEqual(fragment.markdown, source, "A complete quote or prose/list boundary does not need a new separator")
                    XCTAssertEqual(MacMarkdown.markdown(view.attributedString()), source); XCTAssertEqual(state.text, source)
                    if source.hasPrefix(">") { XCTAssertEqual(Array(Document(parsing: fragment.markdown).children).filter { $0 is BlockQuote }.count, 1) }
                }
            }
            try await self.editor("9. Nine\n10. Ten\n", root: true) { view, coordinator, state, _ in
                let end = (view.string as NSString).range(of: "Ten").location - 1
                view.setSelectedRange(NSRange(location: 0, length: end)); try await coordinator.copy(cut: false)
                let fragment = try NativeClipboardFragment.decode(try XCTUnwrap(board.data(forType: .init(NativeClipboardFragment.type))))
                XCTAssertEqual(fragment.markdown, "9. Nine\n\n10\\.")
                let document = Document(parsing: fragment.markdown)
                XCTAssertEqual(document.children.compactMap { ($0 as? Paragraph)?.plainText }, ["10."])
                XCTAssertEqual(MacMarkdown.markdown(view.attributedString()), "9. Nine\n10. Ten\n"); XCTAssertEqual(state.text, "9. Nine\n10. Ten\n")
            }
            try await self.editor("10. Parent\n    - Child\n", root: true) { view, coordinator, state, _ in
                let parent = (view.string as NSString).range(of: "Parent"), child = (view.string as NSString).range(of: "Child")
                let row = (view.string as NSString).paragraphRange(for: child)
                let range = NSRange(location: parent.location + 1, length: row.location + 1 - parent.location - 1)
                view.setSelectedRange(range); try await coordinator.copy(cut: false)
                let fragment = try NativeClipboardFragment.decode(try XCTUnwrap(board.data(forType: .init(NativeClipboardFragment.type))))
                XCTAssertEqual(fragment.markdown, "arent\n•", "A partial visible marker is literal selected text, not a complete list head")
                XCTAssertEqual(state.text, "10. Parent\n    - Child\n")
            }
        }
    }
    func testPasteRefusesToCommitAfterWorkspaceBecomesReadonly() async throws {
        let original = "Original writing.\n"
        try await editor(original, root: true) { view, coordinator, state, _ in
            view.setSelectedRange(NSRange(location: 0, length: 0))
            coordinator.parent.onPasteBusy = { busy in
                if busy {
                    coordinator.parent = MacRichEditor(markdown: original, source: false, editable: false, onChange: { state.text = $0 }, onLink: { _ in }, onSourceChange: { _ in })
                }
            }
            do { try await coordinator.paste(.html(Data("<b>Late paste</b>".utf8))); XCTFail("A paste cannot commit after loading makes the note readonly") }
            catch { XCTAssertTrue(error.localizedDescription.contains("insertion point changed"), error.localizedDescription) }
            XCTAssertEqual(state.text, original)
            XCTAssertEqual(coordinator.lastMarkdown, original)
            XCTAssertFalse(view.isEditable)
        }
    }
    func testInlinePastePreservesTheReceivingRoleAtAParagraphStartAndWholeRow() async throws {
        func structure(_ node: any Markup, owner: Int? = nil, into parents: inout [Int?], parentParagraphs: inout Int?) {
            var owner = owner
            if node is ListItem {
                let index = parents.count; parents.append(owner); owner = index
                let paragraphs = node.children.compactMap { $0 as? Paragraph }
                if paragraphs.first?.plainText == "Parent" { parentParagraphs = paragraphs.count }
            }
            for child in node.children { structure(child, owner: owner, into: &parents, parentParagraphs: &parentParagraphs) }
        }
        for (source, bodyPrefix, owners) in [
            ("- Parent\n  - Child\n\n  Tail paragraph.\n- Sibling\n", "  ", [nil, 0, nil] as [Int?]),
            ("10. Parent\n    - Child\n\n    Tail paragraph.\n11. Sibling\n", "    ", [nil, 0, nil]),
            ("- [x] Parent\n  - Child\n\n  Tail paragraph.\n- Sibling\n", "  ", [nil, 0, nil]),
            ("> - Parent\n>   - Child\n>\n>   Tail paragraph.\n> - Sibling\n", ">   ", [nil, 0, nil]),
            ("- Root\n  - Parent\n    - Child\n\n    Tail paragraph.\n- Sibling\n", "    ", [nil, 0, 1, nil]),
            ("# Tail paragraph.\n", "", []),
            ("> Tail paragraph.\n", "> ", [])
        ] { for ending in ["\n", "\r\n"] { for selectionKind in ["caret", "word", "row"] { for format in ["html", "fragment", "html-break", "plain", "plain-lines", "fragment-row"] {
            if format == "fragment-row" && selectionKind != "row" { continue }
            let source = source.replacingOccurrences(of: "\n", with: ending)
            let lines = format == "html-break" || format == "plain-lines"
            let token = format == "plain-lines" ? (source.hasPrefix("# ") ? "X<br>Y" : "X  " + ending + bodyPrefix + "Y") : format == "html-break" ? "**X**<br>**Y**" : format == "plain" ? "X" : "**X**"
            let expected = selectionKind == "row" ? source.replacingOccurrences(of: "Tail paragraph." + ending, with: token + ending) : source.replacingOccurrences(of: "Tail", with: token + (selectionKind == "caret" ? "Tail" : ""))
            // Core cases retain their current admission policy; Workspace owns
            // the decision to open them in rich mode. Already-admitted roles
            // must stay rich through this actual paste command.
            let initiallyRich = !MacMarkdown.requiresSource(source)
            try await editor(source, root: true) { view, coordinator, state, _ in
                let word = (view.string as NSString).range(of: "Tail")
                guard word.location != NSNotFound else { XCTFail("The receiving paragraph must remain visible"); return }
                let originalStyle = view.attributedString().attribute(.paragraphStyle, at: word.location, effectiveRange: nil) as? NSParagraphStyle
                let originalSize = (view.attributedString().attribute(.font, at: word.location, effectiveRange: nil) as? NSFont)?.pointSize
                let selected = selectionKind == "row" ? (view.string as NSString).paragraphRange(for: word) : NSRange(location: word.location, length: selectionKind == "word" ? word.length : 0)
                view.setSelectedRange(selected)
                let payload: MacClipboard.Payload
                switch format {
                case "html": payload = .html(Data("<strong>X</strong>".utf8))
                case "html-break": payload = .html(Data("<strong>X</strong><br><strong>Y</strong>".utf8))
                case "plain": payload = .plain("X")
                case "plain-lines": payload = .plain("X" + ending + "Y")
                default: payload = .fragment(.init(markdown: "**X**" + (format == "fragment-row" ? ending : "")))
                }
                try await coordinator.paste(payload)
                XCTAssertEqual(state.text, expected)
                var parents: [Int?] = [], paragraphs: Int?
                structure(Document(parsing: state.text), into: &parents, parentParagraphs: &paragraphs)
                XCTAssertEqual(parents, owners); XCTAssertEqual(paragraphs, owners.isEmpty ? nil : 2)
                if initiallyRich {
                    XCTAssertFalse(state.source)
                    XCTAssertEqual(MacMarkdown.render(state.text).string.replacingOccurrences(of: "\u{2028}", with: "\n"), view.string.replacingOccurrences(of: "\u{2028}", with: "\n"))
                    let x = (view.string as NSString).range(of: "X")
                    guard x.location != NSNotFound else { XCTFail("The pasted text must remain visible"); return }
                    let style = view.attributedString().attribute(.paragraphStyle, at: x.location, effectiveRange: nil) as? NSParagraphStyle
                    XCTAssertEqual(style?.firstLineHeadIndent, originalStyle?.firstLineHeadIndent)
                    XCTAssertEqual(style?.headIndent, originalStyle?.headIndent)
                    XCTAssertEqual((view.attributedString().attribute(.font, at: x.location, effectiveRange: nil) as? NSFont)?.pointSize, originalSize)
                    XCTAssertEqual(view.selectedRange(), NSRange(location: selected.location + (lines ? 3 : 1), length: 0))
                }
                coordinator.action("undo"); XCTAssertEqual(state.text, source); XCTAssertEqual(view.selectedRange(), selected)
                coordinator.action("redo"); XCTAssertEqual(state.text, expected)
                if initiallyRich {
                    view.insertText("!", replacementRange: view.selectedRange())
                    let insertion = selectionKind == "row" ? token + ending : token + (selectionKind == "caret" ? "Tail" : "")
                    let typed = selectionKind == "row" ? token + "!" + ending : token + "!" + (selectionKind == "caret" ? "Tail" : "")
                    XCTAssertEqual(state.text, expected.replacingOccurrences(of: insertion, with: typed))
                }
            }
        } } } }
    }

