            let source = "9. Parent\n   - Child\n\nBefore abcd after\n".replacingOccurrences(of: "\n", with: ending)
            try await editor(source, root: true) { view, coordinator, state, _ in
                let child = (view.string as NSString).range(of: "Child")
                let childRow = (view.string as NSString).paragraphRange(for: child)
                view.setSelectedRange(NSRange(location: childRow.location, length: 0))
                view.insertText("\n", replacementRange: view.selectedRange())
                let before = state.text, body = (view.string as NSString).range(of: "abcd")
                let selected = NSRange(location: body.location + 2, length: 0)
                view.setSelectedRange(selected)
                do { try await coordinator.paste(.fragment(.init(markdown: "- X\n- Y\n"))) }
                catch { XCTFail("An unrelated temporary list must not block ordinary prose paste: \(error.localizedDescription)"); return }
                let expected = before.replacingOccurrences(of: "abcd", with: "ab" + ending + ending + "- X" + ending + "- Y" + ending + ending + "cd")
                XCTAssertEqual(state.text, expected)
                let y = (view.string as NSString).range(of: "Y")
                XCTAssertEqual(view.selectedRange(), NSRange(location: y.location + 1, length: 0))
                coordinator.action("undo"); XCTAssertEqual(state.text, before); XCTAssertEqual(view.selectedRange(), selected)
                coordinator.action("redo"); XCTAssertEqual(state.text, expected)
            }
        }
        for ending in ["\n", "\r\n"] { for code in [true, false] { for format in ["fragment", "html"] {
            let source = "Before abcd after\n".replacingOccurrences(of: "\n", with: ending)
            let card = code ? "```swift\n\n```\n" : "| Z |\n| --- |\n|  |\n"
            let expected = ("Before ab\n\n" + card + "\ncd after\n").replacingOccurrences(of: "\n", with: ending)
            try await editor(source, root: true) { view, coordinator, state, _ in
                let selected = NSRange(location: (view.string as NSString).range(of: "abcd").location + 2, length: 0)
                view.setSelectedRange(selected)
                let html = code ? "<pre><code class='language-swift'></code></pre>" : "<table><tr><th>Z</th></tr><tr><td></td></tr></table>"
                try await coordinator.paste(format == "html" ? .html(Data(html.utf8)) : .fragment(.init(markdown: card.replacingOccurrences(of: "\n", with: ending))))
                XCTAssertEqual(state.text, expected); XCTAssertFalse(state.source)
                let placeholder = (view.string as NSString).range(of: "\u{200B}")
                guard placeholder.location != NSNotFound else { XCTFail("The empty card must remain editable"); return }
                XCTAssertEqual(view.selectedRange(), NSRange(location: placeholder.location + 1, length: 0))
                coordinator.action("undo"); XCTAssertEqual(state.text, source); XCTAssertEqual(view.selectedRange(), selected)
                coordinator.action("redo"); XCTAssertEqual(state.text, expected)
                view.insertText("Y", replacementRange: view.selectedRange())
                let typed = code ? expected.replacingOccurrences(of: "```swift" + ending + ending, with: "```swift" + ending + "Y" + ending) : expected.replacingOccurrences(of: "|  |", with: "| Y |")
                XCTAssertEqual(state.text, typed)
                XCTAssertEqual(MacMarkdown.render(state.text).string, view.string)
            }
        } } }
        for (card, bodyEnd, typedCard) in [
            ("```swift\nZ\n\n```\n", "Z\n", "```swift\nZ\nY\n```\n"),
            ("```swift\nZ\nW\n```\n", "W", "```swift\nZ\nWY\n```\n")
        ] { for ending in ["\n", "\r\n"] {
            let source = "Before abcd after\n".replacingOccurrences(of: "\n", with: ending)
            let expected = ("Before ab\n\n" + card + "\ncd after\n").replacingOccurrences(of: "\n", with: ending)
            try await editor(source, root: true) { view, coordinator, state, _ in
                let selected = NSRange(location: (view.string as NSString).range(of: "abcd").location + 2, length: 0)
                view.setSelectedRange(selected)
                try await coordinator.paste(.fragment(.init(markdown: card.replacingOccurrences(of: "\n", with: ending))))
                XCTAssertEqual(state.text, expected); XCTAssertFalse(state.source)
                let body = (view.string as NSString).range(of: bodyEnd.replacingOccurrences(of: "\n", with: ending))
                guard body.location != NSNotFound else { XCTFail("The pasted code body must remain visible"); return }
                XCTAssertEqual(view.selectedRange(), NSRange(location: NSMaxRange(body), length: 0))
                coordinator.action("undo"); XCTAssertEqual(state.text, source); XCTAssertEqual(view.selectedRange(), selected)
                coordinator.action("redo"); XCTAssertEqual(state.text, expected)
                view.insertText("Y", replacementRange: view.selectedRange())
                XCTAssertEqual(state.text, ("Before ab\n\n" + typedCard + "\ncd after\n").replacingOccurrences(of: "\n", with: ending))
                XCTAssertEqual(MacMarkdown.render(state.text).string, view.string)
            }
        } }
    }

    func testNestedHTMLChecklistsKeepCheckboxesOnTheirOwnItems() async throws {
        for (html, fragment, owners, checked) in [
            ("<ul><li>X<ul><li><input type='checkbox' checked>Y</li></ul></li></ul>", "- X\n  - [x] Y\n", [nil, 0] as [Int?], [nil, true] as [Bool?]),
