            ("<ul><li><input type='checkbox'>X<ul><li><input type='checkbox' checked>Y</li></ul></li></ul>", "- [ ] X\n  - [x] Y\n", [nil, 0], [false, true]),
            ("<ul><li><label><input type='checkbox' checked>X</label><ul><li>Y</li></ul></li></ul>", "- [x] X\n  - Y\n", [nil, 0], [true, nil]),
            ("<ul><li>X<ul><li><input type='checkbox' checked>Y</li></ul><input type='checkbox'></li></ul>", "- [ ] X\n  - [x] Y\n", [nil, 0], [false, true]),
