            ("<ul><li>X<ul><li><input type='checkbox' checked>Middle<ul><li><input type='checkbox'>Y</li></ul></li></ul></li></ul>", "- X\n  - [x] Middle\n    - [ ] Y\n", [nil, 0, 1], [nil, true, false]),
            ("<ul __lexicallisttype='check'><li role='checkbox' aria-checked='true'>X<ul><li>Y</li></ul></li></ul>", "- [x] X\n  - Y\n", [nil, 0], [true, nil]),
            ("<ul><li>X<ul __lexicallisttype='check'><li role='checkbox' aria-checked='false'>Y</li></ul></li></ul>", "- X\n  - [ ] Y\n", [nil, 0], [nil, false]),
            ("<ul><li aria-checked='false'><input type='checkbox' checked>X<ul><li>Y</li></ul></li></ul>", "- [ ] X\n  - Y\n", [nil, 0], [false, nil]),
            ("<ul><li aria-checked='mixed'>X<ul><li><input type='checkbox' checked>Y</li></ul></li></ul>", "- X\n  - [x] Y\n", [nil, 0], [nil, true]),
