            ("<ul><li><input type='checkbox' checked><ul><li>Y</li></ul></li></ul>", "- [x] \u{200B}\n  - Y\n", [nil, 0], [true, nil]),
            ("<ul><li aria-checked='false'><ul><li>Y</li></ul></li></ul>", "- [ ] \u{200B}\n  - Y\n", [nil, 0], [false, nil]),
            ("<ul><li><ul><li><input type='checkbox' checked><ul><li>Y</li></ul></li></ul></li></ul>", "- \n  - [x] \u{200B}\n    - Y\n", [nil, 0, 1], [nil, true, nil]),
            ("<ul><li><input type='checkbox' checked><ul><li>Y</li></ul>Tail</li></ul>", "- [x] \u{200B}\n  - Y\n\n  Tail\n", [nil, 0], [true, nil]),
            ("<ul><li><input type='checkbox' checked></li><li>Y</li></ul>", "- [x] \u{200B}\n- Y\n", [nil, nil], [true, nil]),
            ("<ul><li>X<ol start='3'><li>Y</li></ol></li></ul>", "- X\n\n  3. Y\n", [nil, 0], [nil, nil]),
            ("<ul><li><input type='checkbox' checked>X<ol start='3'><li>Y</li></ol></li></ul>", "- [x] X\n\n  3. Y\n", [nil, 0], [true, nil]),
            ("<ul><li><input type='checkbox' checked><ol start='3'><li>Y</li></ol></li></ul>", "- [x] \u{200B}\n\n  3. Y\n", [nil, 0], [true, nil]),
            ("<ul><li aria-checked='false'><ol><li value='10'>Y</li></ol></li></ul>", "- [ ] \u{200B}\n\n  10. Y\n", [nil, 0], [false, nil]),
            ("<ul><li><ol start='3'><li>Y</li></ol></li></ul>", "- \n  3. Y\n", [nil, 0], [nil, nil]),
            ("<ol start='10'><li><ol start='3'><li>Y</li></ol></li></ol>", "10. \n    3. Y\n", [nil, 0], [nil, nil]),
            ("<ul><li><p>X</p><ol start='3'><li>Y</li></ol></li></ul>", "- X\n\n  3. Y\n", [nil, 0], [nil, nil]),
            ("<ul><li>X<ul><li>Middle</li></ul>Tail<ol start='3'><li>Y</li></ol></li></ul>", "- X\n  - Middle\n\n  Tail\n\n  3. Y\n", [nil, 0, 0], [nil, nil, nil]),
            ("<ul><li>X<ul><li>Middle</li></ul><ol start='3'><li>Y</li></ol></li></ul>", "- X\n  - Middle\n  3. Y\n", [nil, 0, 0], [nil, nil, nil]),
            ("<ul><li>X<ol start='1'><li>Y</li></ol></li></ul>", "- X\n  1. Y\n", [nil, 0], [nil, nil]),
            ("<ol start='999999999'><li>Y</li></ol>", "999999999. Y\n", [nil], [nil]),
            ("<ul start='9223372036854775807'><li value='9223372036854775807'>Y</li></ul>", "- Y\n", [nil], [nil]),
            ("<ul><li>X<ol start=' +3 '><li>Y</li></ol></li></ul>", "- X\n\n  3. Y\n", [nil, 0], [nil, nil]),
            ("<ul><li>X<ol><li value=' +10 '>Y</li></ol></li></ul>", "- X\n\n  10. Y\n", [nil, 0], [nil, nil]),
            ("<ol start='unknown'><li value='unknown'>Y</li></ol>", "1. Y\n", [nil], [nil]),
            ("<ol start='0'><li>Y</li></ol>", "0. Y\n", [nil], [nil]),
            ("<ul><li>X<ol><li value='0'>Y</li></ol></li></ul>", "- X\n\n  0. Y\n", [nil, 0], [nil, nil])
        ] { for ending in ["\n", "\r\n"] {
            let source = "Before abcd after" + ending
            let expected = "Before ab" + ending + ending + fragment.replacingOccurrences(of: "\n", with: ending) + ending + "cd after" + ending
            try await editor(source, root: true) { view, coordinator, state, _ in
                let body = (view.string as NSString).range(of: "abcd")
                let selected = NSRange(location: body.location + 2, length: 0)
                view.setSelectedRange(selected)
                do { try await coordinator.paste(.html(Data(html.utf8))) }
                catch { XCTFail("A nested checklist must paste as a list: \(error.localizedDescription)"); return }
                XCTAssertEqual(state.text, expected); XCTAssertFalse(state.source)
                var parents: [Int?] = [], states: [Bool?] = []
                func visit(_ node: any Markup, parent: Int? = nil) {
                    var owner = parent
                    if let item = node as? ListItem {
                        let index = parents.count; parents.append(parent); states.append(item.checkbox.map { $0 == .checked }); owner = index
                    }
                    for child in node.children { visit(child, parent: owner) }
                }
                visit(Document(parsing: state.text)); XCTAssertEqual(parents, owners); XCTAssertEqual(states, checked)
                XCTAssertEqual(view.string.filter { $0 == "☑" }.count, checked.filter { $0 == true }.count)
                XCTAssertEqual(view.string.filter { $0 == "☐" }.count, checked.filter { $0 == false }.count)
                XCTAssertEqual(MacMarkdown.render(state.text).string, view.string)
                let last = fragment.hasSuffix("Tail\n") ? "Tail" : "Y"
                let y = (view.string as NSString).range(of: last)
                guard y.location != NSNotFound else { XCTFail("The last body must remain visible"); return }
                XCTAssertEqual(view.selectedRange(), NSRange(location: y.location + last.utf16.count, length: 0))
                coordinator.action("undo"); XCTAssertEqual(state.text, source); XCTAssertEqual(view.selectedRange(), selected)
                coordinator.action("redo"); XCTAssertEqual(state.text, expected)
                view.insertText("!", replacementRange: view.selectedRange())
                XCTAssertEqual(state.text, expected.replacingOccurrences(of: last + ending, with: last + "!" + ending))
            }
        } }
        for (html, marker) in [("<ul><li></li></ul>", "- "), ("<ol start='10'><li></li></ol>", "10. ")] { for ending in ["\n", "\r\n"] {
            let source = "Before abcd after" + ending
            let expected = "Before ab" + ending + ending + marker + "\u{200B}" + ending + ending + "cd after" + ending
            try await editor(source, root: true) { view, coordinator, state, _ in
                let target = (view.string as NSString).range(of: "abcd")
                guard target.location != NSNotFound else { XCTFail("The receiving paragraph must remain visible"); return }
                let selected = NSRange(location: target.location + 2, length: 0)
                view.setSelectedRange(selected)
                try await coordinator.paste(.html(Data(html.utf8)))
                XCTAssertEqual(state.text, expected); XCTAssertFalse(state.source)
                let visible = marker == "- " ? "• " : marker
                let item = (view.string as NSString).range(of: visible)
                guard item.location != NSNotFound else { XCTFail("An empty copied item must stay native"); return }
                XCTAssertEqual(view.selectedRange(), NSRange(location: NSMaxRange(item), length: 0))
                XCTAssertEqual(MacMarkdown.render(state.text).string, view.string)
                coordinator.action("undo"); XCTAssertEqual(state.text, source); XCTAssertEqual(view.selectedRange(), selected)
                coordinator.action("redo"); XCTAssertEqual(state.text, expected)
                view.insertText("!", replacementRange: view.selectedRange())
                XCTAssertEqual(state.text, expected.replacingOccurrences(of: marker + "\u{200B}", with: marker + "!"))
            }
        } }
        for value in ["-1", "1000000000", "9223372036854775807", "9223372036854775808", "start-overflow", "implicit"] {
            let source = "Before target after\n"
            try await editor(source, root: true) { view, coordinator, state, _ in
                let selected = (view.string as NSString).range(of: "target")
                view.setSelectedRange(selected)
                let visible = view.string, undo = view.undoManager?.undoActionName
                let html = value == "implicit" ? "<ol start='999999999'><li>X</li><li>Y</li></ol>" : value == "start-overflow" ? "<ol start='9223372036854775808'><li>Y</li></ol>" : "<ol><li value='" + value + "'>Y</li></ol>"
                do { try await coordinator.paste(.html(Data(html.utf8))); XCTFail("An unsupported ordinal must be refused before paste") }
                catch { XCTAssertEqual(error.localizedDescription, "This copied list uses unsupported numbering. Use Paste plain text.") }
                XCTAssertEqual(state.text, source); XCTAssertEqual(view.string, visible); XCTAssertEqual(view.selectedRange(), selected)
                XCTAssertEqual(view.undoManager?.undoActionName, undo)
            }
        }
    }

    func testParagraphPasteClosesTheReceivingListAndPreservesItsChildren() async throws {
        for (source, first, from, last, through, kind, count, expected) in [
            ("- abcd\n  - Child\n- Sib\n", "abcd", 2, "abcd", 2, "normal", 3, "- ab**X**\n\n**Y**cd\n\n- Child\n- Sib\n"),
            ("- abcd\n  - Child\n- Sib\n", "abcd", 1, "abcd", 3, "normal", 3, "- a**X**\n\n**Y**d\n\n- Child\n- Sib\n"),
            ("> - abcd\n>   - Child\n> - Sib\n", "abcd", 2, "abcd", 2, "normal", 3, "> - ab**X**\n> \n> **Y**cd\n> \n> - Child\n> - Sib\n"),
            ("- Parent\n  - A\n- Sibling\n  - B\n- Last\n", "Parent", 3, "Sibling", 2, "normal", 3, "- Par**X**\n\n**Y**bling\n\n- B\n- Last\n"),
            ("- abcd\n  - Child\n- Sib\n", "abcd", 2, "abcd", 2, "blank", 3, "- ab**X**\n\n\u{200B}\n\n**Y**cd\n\n- Child\n- Sib\n"),
            ("- P\n\n  abcd\n  - Child\n- Sib\n", "abcd", 2, "abcd", 2, "normal", 3, "- P\n\n  ab**X**\n\n**Y**cd\n\n- Child\n- Sib\n"),
            ("- abcd\n  - Child\n- Sib\n", "abcd", 2, "abcd", 2, "soft", 3, "- ab**X wrap**\n\n**Y**cd\n\n- Child\n- Sib\n"),
            ("> abcd\n", "abcd", 2, "abcd", 2, "quote", 0, "> ab**XY**cd\n"),
            ("- Parent\n  - Child\n\n  abcd\n- Sib\n", "abcd", 2, "abcd", 2, "tail", 3, "- Parent\n  - Child\n\n  ab**X**\n\n**Y**cd\n\n- Sib\n"),
            ("# abcd\n", "abcd", 2, "abcd", 2, "normal", 0, "# ab**X**\n\n**Y**cd\n"),
            ("Before abcd after\n", "abcd", 2, "abcd", 2, "normal", 0, "Before ab**X**\n\n**Y**cd after\n")
        ] { for ending in ["\n", "\r\n"] { for html in [false, true] {
            let source = source.replacingOccurrences(of: "\n", with: ending), expected = expected.replacingOccurrences(of: "\n", with: ending)
            try await editor(source, root: true) { view, coordinator, state, _ in
                let body = (view.string as NSString).range(of: first), end = (view.string as NSString).range(of: last)
                guard body.location != NSNotFound, end.location != NSNotFound else { XCTFail("The paste target must remain visible"); return }
                let selected = NSRange(location: body.location + from, length: end.location + through - body.location - from)
                view.setSelectedRange(selected)
                let middle = kind == "blank" ? "<p><br></p>" : ""
                let firstText = kind == "soft" ? "X\nwrap" : "X"
                let markdown = "**" + firstText + "**\n\n" + (kind == "blank" ? "\u{200B}\n\n" : "") + "**Y**\n"
                try await coordinator.paste(html ? .html(Data(("<p><strong>" + firstText + "</strong></p>" + middle + "<p><strong>Y</strong></p>").utf8)) : .fragment(.init(markdown: markdown)))
                XCTAssertEqual(state.text, expected); XCTAssertFalse(state.source)
                func parents(_ node: any Markup, owner: Int? = nil, into result: inout [Int?]) {
                    var owner = owner
                    if node is ListItem { let index = result.count; result.append(owner); owner = index }
                    for child in node.children { parents(child, owner: owner, into: &result) }
                }
                var ownership: [Int?] = []; parents(Document(parsing: state.text), into: &ownership)
                XCTAssertEqual(ownership, kind == "tail" ? [nil, 0, nil] : Array<Int?>(repeating: nil, count: count))
                func strong(_ node: any Markup) -> Int { (node is Strong ? 1 : 0) + node.children.reduce(0) { $0 + strong($1) } }
                XCTAssertEqual(strong(Document(parsing: state.text)), kind == "quote" ? 1 : 2)
                XCTAssertEqual(MacMarkdown.render(state.text).string, view.string)
                let y = (view.string as NSString).range(of: "Y")
                guard y.location != NSNotFound else { XCTFail("The final pasted paragraph must remain visible"); return }
                let afterY = y.location + 1
                XCTAssertEqual(view.selectedRange(), NSRange(location: afterY, length: 0))
                XCTAssertEqual(view.undoManager?.undoActionName, "Paste")
                coordinator.action("undo"); XCTAssertEqual(state.text, source); XCTAssertEqual(view.selectedRange(), selected)
                coordinator.action("redo"); XCTAssertEqual(state.text, expected)
                view.insertText("!", replacementRange: view.selectedRange())
                let tail = kind == "quote" ? "**XY**" : "**Y**"
                XCTAssertEqual(state.text, expected.replacingOccurrences(of: tail, with: tail + "!"))
            }
        } } }
    }
    func testStructuredPasteLeavingPartialCardsKeepsAllTextInTheReceivingModel() async throws {
        let defaults = UserDefaults.standard, key = "zerus.mac.codeBlocks", previous = defaults.object(forKey: key)
        defaults.set(true, forKey: key)
        defer { if let previous { defaults.set(previous, forKey: key) } else { defaults.removeObject(forKey: key) } }
        for table in [false, true] { for middle in ["paragraphs", "heading", "code", "table"] { for html in [false, true] { for ending in ["\n", "\r\n", "\r"] { for quoted in [false, true] {
            let rows = table ? ["| A | B |", "| --- | --- |", "| abcdef | Keep |"] : ["```swift", "abcdef", "```"]
            let source = (["Parent", ""] + rows + ["", "Sibling"]).map { (quoted ? "> " : "") + $0 }.joined(separator: ending) + ending
            try await editor(source, root: true) { view, coordinator, state, _ in
                let raw = view.string as NSString, start = raw.range(of: "abcdef").location + 3
                let selection = NSRange(location: start, length: raw.range(of: "Sibling").location + 3 - start)
                view.setSelectedRange(selection)
                let block = middle == "heading" ? "## Z" : middle == "code" ? "```swift\nZ\n```" : middle == "table" ? "| Z |\n| --- |\n| V |" : ""
                let markdown = "X\n\n" + (block.isEmpty ? "" : block + "\n\n") + "Y\n"
                let tag = middle == "heading" ? "<h2>Z</h2>" : middle == "code" ? "<pre><code class='language-swift'>Z</code></pre>" : middle == "table" ? "<table><tr><th>Z</th></tr><tr><td>V</td></tr></table>" : ""
                try await coordinator.paste(html ? .html(Data(("<p>X</p>" + tag + "<p>Y</p>").utf8)) : .fragment(.init(markdown: markdown)))
                func content(_ source: String) -> (prose: [String], codes: [String], cells: [String]) {
                    var prose: [String] = [], codes: [String] = [], cells: [String] = []
                    func text(_ node: any Markup) -> String { (node as? Markdown.Text)?.string ?? (node as? InlineCode)?.code ?? node.children.map(text).joined() }
                    func walk(_ node: any Markup, inTable: Bool = false) {
                        if let p = node as? Paragraph, !inTable { prose.append(text(p)) }
                        if let c = node as? CodeBlock { codes.append(c.code.replacingOccurrences(of: "\n", with: "")) }
                        if let c = node as? Markdown.Table.Cell { cells.append(text(c)) }
                        for child in node.children { walk(child, inTable: inTable || node is Markdown.Table) }
                    }
                    walk(Document(parsing: source)); return (prose, codes, cells)
                }
                let saved = state.text, parsed = content(saved)
                let body = "abcX" + (middle == "paragraphs" ? "" : middle == "table" ? "ZV" : "Z") + "Y"
                XCTAssertFalse(state.source)
                XCTAssertEqual(parsed.prose, ["Parent"])
                XCTAssertEqual(parsed.codes, table ? [] : [body + "ling"])
                XCTAssertEqual(parsed.cells, table ? ["A", "B", body + "ling", ""] : [])
                let caret = view.selectedRange()
                XCTAssertEqual((view.string as NSString).substring(with: NSRange(location: caret.location, length: 4)), "ling", "The caret must stay before the surviving suffix")
                coordinator.action("undo"); XCTAssertEqual(state.text, source); XCTAssertEqual(view.selectedRange(), selection)
                coordinator.action("redo"); XCTAssertEqual(state.text, saved); XCTAssertEqual(view.selectedRange(), caret)
                view.insertText("!", replacementRange: caret)
                XCTAssertEqual(content(state.text).codes, table ? [] : [body + "!ling"])
                XCTAssertEqual(content(state.text).cells, table ? ["A", "B", body + "!ling", ""] : [])
            }
        } } } } }
    }
