            let source = (["Parent", ""] + rows + ["", "Sibling"]).map { (quoted ? "> " : "") + $0 }.joined(separator: ending) + ending
            try await editor(source, root: true) { view, coordinator, state, _ in
                let raw = view.string as NSString, start = raw.range(of: "Parent").location + 3
                let selection = NSRange(location: start, length: raw.range(of: "abcdef").location + 3 - start)
                view.setSelectedRange(selection)
                let block = middle == "heading" ? "## Z" : middle == "code" ? "```swift\nZ\n```" : middle == "table" ? "| Z |\n| --- |\n| V |" : ""
                let markdown = "X\n\n" + (block.isEmpty ? "" : block + "\n\n") + "Y\n"
                let tag = middle == "heading" ? "<h2>Z</h2>" : middle == "code" ? "<pre><code class='language-swift'>Z</code></pre>" : middle == "table" ? "<table><tr><th>Z</th></tr><tr><td>V</td></tr></table>" : ""
                let markup = "<p>X</p>" + tag + "<p>Y</p>"
                try await coordinator.paste(html ? .html(Data(markup.utf8)) : .fragment(.init(markdown: markdown)))
                let saved = state.text
                func content(_ source: String) -> (prose: [String], headings: [String], codes: [String], cells: [String]) {
                    var prose: [String] = [], headings: [String] = [], codes: [String] = [], cells: [String] = []
                    func walk(_ node: any Markup, inTable: Bool = false) {
                        if let p = node as? Paragraph, !inTable { prose.append(p.plainText) }
                        if let h = node as? Heading { headings.append(h.plainText) }
                        if let c = node as? CodeBlock { codes.append(c.code) }
                        if let c = node as? Markdown.Table.Cell { cells.append(c.plainText) }
                        for child in node.children { walk(child, inTable: inTable || node is Markdown.Table) }
                    }
                    walk(Document(parsing: source)); return (prose, headings, codes, cells)
                }
                let parsed = content(saved)
                XCTAssertFalse(state.source)
                XCTAssertEqual(parsed.prose, ["ParX", "Y", "Sibling"])
                XCTAssertEqual(parsed.headings, middle == "heading" ? ["Z"] : [])
                XCTAssertEqual(parsed.codes, (middle == "code" ? ["Z\n"] : []) + (table ? [] : ["def\n"]))
                XCTAssertEqual(parsed.cells, (middle == "table" ? ["Z", "V"] : []) + (table ? ["", "", "def", "Keep"] : []))
                func nativeRows(_ text: String) -> [String] {
                    text.replacingOccurrences(of: "\r\n", with: "\n").replacingOccurrences(of: "\r", with: "\n").replacingOccurrences(of: "\u{200b}", with: "").components(separatedBy: "\n")
                }
                XCTAssertEqual(nativeRows(MacMarkdown.render(saved).string), nativeRows(view.string), "Reopening must retain the pasted text, card cells and native paragraph separators")
                func top(_ label: String, in editor: NSTextView) throws -> CGFloat {
                    let range = (editor.string as NSString).range(of: label)
                    guard range.location != NSNotFound else { XCTFail("The layout anchor must remain visible"); return .nan }
                    let manager = try XCTUnwrap(editor.layoutManager), container = try XCTUnwrap(editor.textContainer)
                    manager.ensureLayout(for: container)
                    let glyphs = manager.glyphRange(forCharacterRange: range, actualCharacterRange: nil)
                    return manager.boundingRect(forGlyphRange: glyphs, in: container).minY
                }
                let cardTop = try top("def", in: view), siblingTop = try top("Sibling", in: view)
                try await self.editor(saved, root: true) { reopened, _, _, _ in
                    let scenario = "table=\(table), middle=\(middle), html=\(html), quoted=\(quoted), ending=\(ending.debugDescription)"
                    XCTAssertEqual(try top("def", in: reopened), cardTop, accuracy: 0.5, "Reopening must retain the card's vertical position: " + scenario)
                    XCTAssertEqual(try top("Sibling", in: reopened), siblingTop, accuracy: 0.5, "Reopening must retain the following paragraph's vertical position: " + scenario)
                }
                let caret = view.selectedRange()
                XCTAssertEqual((view.string as NSString).substring(with: NSRange(location: caret.location - 1, length: 1)), "Y", "table=\(table) middle=\(middle) html=\(html) quoted=\(quoted)")
                coordinator.action("undo"); XCTAssertEqual(state.text, source); XCTAssertEqual(view.selectedRange(), selection)
                coordinator.action("redo"); XCTAssertEqual(state.text, saved); XCTAssertEqual(view.selectedRange(), caret)
                view.insertText("!", replacementRange: caret)
                XCTAssertEqual(content(state.text).prose, ["ParX", "Y!", "Sibling"])
                XCTAssertEqual(content(state.text).codes, parsed.codes); XCTAssertEqual(content(state.text).cells, parsed.cells)
            }
        } } } } }
    }
    func testImagePasteIntoCodeKeepsPortableReferencesAndImportedBytes() async throws {
        for html in [false, true] { for outgoing in [false, true] {
            let source = "```swift\nabcdef\n```\n\nSibling\n"
            try await editor(source, root: true) { view, coordinator, state, root in
                let raw = view.string as NSString, start = raw.range(of: "abcdef").location + 3
                let selection = NSRange(location: start, length: outgoing ? raw.range(of: "Sibling").location + 3 - start : 0)
                view.setSelectedRange(selection)
                let payload: MacClipboard.Payload = html
                    ? .html(Data(("<img alt='Caption' src='data:image/png;base64," + self.png.base64EncodedString() + "'>").utf8))
                    : .fragment(.init(markdown: "![Caption](image.png)", resources: [.init(reference: "image.png", path: nil, name: "image.png", bytes: self.png)]))
                try await coordinator.paste(payload)
                let saved = state.text
                var bodies: [String] = []
                func walk(_ node: any Markup) {
                    if let code = node as? CodeBlock { bodies.append(code.code) }
                    for child in node.children { walk(child) }
                }
                walk(Document(parsing: saved))
                let body = try XCTUnwrap(bodies.first)
                XCTAssertEqual(bodies.count, 1); XCTAssertFalse(state.source)
                XCTAssertTrue(body.hasPrefix("abc")); XCTAssertTrue(body.contains("Caption"))
                XCTAssertFalse(body.contains("\u{fffc}"), "Code must contain a portable reference rather than an attachment placeholder")
                XCTAssertTrue(body.hasSuffix(outgoing ? "ling\n" : "def\n"))
                let assets = try FileManager.default.contentsOfDirectory(at: try XCTUnwrap(root).appendingPathComponent("assets"), includingPropertiesForKeys: nil)
                XCTAssertEqual(assets.count, 1)
                let asset = try XCTUnwrap(assets.first)
                XCTAssertEqual(try Data(contentsOf: asset), self.png)
                XCTAssertTrue(body.contains(asset.lastPathComponent), "Every imported image must remain referenced by the code literal")
                let caret = view.selectedRange()
                coordinator.action("undo"); XCTAssertEqual(state.text, source); XCTAssertEqual(view.selectedRange(), selection)
                coordinator.action("redo"); XCTAssertEqual(state.text, saved); XCTAssertEqual(view.selectedRange(), caret)
                view.insertText("!", replacementRange: caret)
                XCTAssertTrue(state.text.contains("!" + (outgoing ? "ling" : "def")))
            }
        } }
    }
    func testMultilinePasteAcrossPartialCardsKeepsNativeModelsAndTheInsertionCaret() async throws {
        for table in [false, true] { for outgoing in [false, true] { for quoted in [false, true] { for ending in ["\n", "\r\n", "\r"] { for format in ["plain", "fragment", "html", "plain-leading", "plain-trailing", "plain-empty-line", "plain-break"] { for offset in outgoing ? [3] : [0, 3] {
            let quote = quoted ? "> " : ""
            let rows = table ? ["| A | B |", "| :---: | ---: |", "| abcdef | Keep |"] : ["```swift", "abcdef", "```"]
            let source = (["Parent", ""] + rows + ["", "Sibling"]).map { quote + $0 }.joined(separator: ending) + ending
            try await editor(source, root: true) { view, coordinator, state, root in
                let raw = view.string as NSString, first = raw.range(of: outgoing ? "abcdef" : "Parent"), last = raw.range(of: outgoing ? "Sibling" : "abcdef")
                let selected = NSRange(location: first.location + offset, length: last.location + 3 - first.location - offset)
                view.setSelectedRange(selected)
                let body = format == "plain-leading" ? "\nX" : format == "plain-trailing" ? "X\n" : format == "plain-empty-line" ? "X\n\nY" : format == "plain-break" ? "\n" : "X\nY"
                let flat = body.replacingOccurrences(of: "\n", with: "")
                let payload: MacClipboard.Payload = format.hasPrefix("plain") ? .plain(body.replacingOccurrences(of: "\n", with: ending)) : format == "fragment" ? .fragment(.init(markdown: "**X**<br>**Y**")) : .html(Data("<strong>X<br>Y</strong>".utf8))
                try await coordinator.paste(payload)
                func content(_ source: String) -> (code: [String], cells: [String], prose: [String], strong: String, breaks: Int) {
                    var code: [String] = [], cells: [String] = [], prose: [String] = [], strong = "", breaks = 0
                    func text(_ node: any Markup) -> String { (node as? Markdown.Text)?.string ?? node.children.map(text).joined() }
                    func walk(_ node: any Markup, inTable: Bool = false) {
                        if let node = node as? CodeBlock { code.append(node.code) }
                        if node is Markdown.Table.Cell { cells.append(text(node)) }
                        if !inTable, let node = node as? Paragraph { prose.append(text(node).replacingOccurrences(of: "\u{200b}", with: "")) }
                        if let node = node as? Strong { strong += text(node) }
                        if node is LineBreak || (node as? InlineHTML)?.rawHTML.lowercased() == "<br>" { breaks += 1 }
                        for child in node.children { walk(child, inTable: inTable || node is Markdown.Table) }
                    }
                    walk(Document(parsing: source)); return (code, cells, prose, strong, breaks)
                }
                let saved = state.text, parsed = content(saved)
                XCTAssertFalse(state.source)
                let document = Document(parsing: saved)
                XCTAssertEqual(document.childCount, quoted ? 1 : outgoing ? 2 : 3)
                if quoted { XCTAssertTrue(document.child(at: 0) is BlockQuote, "Pasting over the first character must retain its quote container") }
                XCTAssertEqual(parsed.code, table ? [] : [outgoing ? "abc" + body + "ling\n" : "def\n"])
                XCTAssertEqual(parsed.cells, table ? (outgoing ? ["A", "B", "abc" + flat + "ling", ""] : ["", "", "def", "Keep"]) : [])
                XCTAssertEqual(parsed.prose, outgoing ? ["Parent"] : [(offset == 0 ? "" : "Par") + flat, "Sibling"])
                XCTAssertEqual(parsed.strong, format.hasPrefix("plain") || outgoing && !table ? "" : "XY")
                XCTAssertEqual(parsed.breaks, outgoing && !table ? 0 : body.filter { $0 == "\n" }.count)
                let caret = NSRange(location: selected.location + (outgoing && !table ? body.replacingOccurrences(of: "\n", with: ending).utf16.count : body.utf16.count), length: 0)
                XCTAssertEqual(view.selectedRange(), caret); XCTAssertEqual(view.undoManager?.undoActionName, "Paste")
                func visible(_ text: String) -> String { text.replacingOccurrences(of: "\r\n", with: "\n").replacingOccurrences(of: "\r", with: "\n").replacingOccurrences(of: "\u{2028}", with: "\n").replacingOccurrences(of: "\u{200b}", with: "") }
                XCTAssertEqual(visible(MacMarkdown.render(saved).string), visible(view.string), "Reopening must retain the native block boundaries")
                coordinator.action("undo"); XCTAssertEqual(state.text, source); XCTAssertEqual(view.selectedRange(), selected)
                coordinator.action("redo"); XCTAssertEqual(state.text, saved); XCTAssertEqual(view.selectedRange(), caret)
                view.insertText("!", replacementRange: view.selectedRange())
                let typed = content(state.text)
                XCTAssertEqual(typed.code, table ? [] : [outgoing ? "abc" + body + "!ling\n" : "def\n"])
                XCTAssertEqual(typed.cells, table ? (outgoing ? ["A", "B", "abc" + flat + "!ling", ""] : ["", "", "def", "Keep"]) : [])
                XCTAssertEqual(typed.prose, outgoing ? ["Parent"] : [(offset == 0 ? "" : "Par") + flat + "!", "Sibling"])
                XCTAssertFalse(FileManager.default.fileExists(atPath: try XCTUnwrap(root).appendingPathComponent("assets").path))
            }
        } } } } } }
    }
    func testInlinePasteAcrossListSelectionsPreservesSurvivorsAndUndo() async throws {
