            ("- Parent\n\n  10. Child\n      - Grand\n- Sibling\n", "Parent", 3, "Child", 2, "- Par{X}ild\n  1. Grand\n- Sibling\n", "  ", [nil, 0, nil] as [Int?]),
            ("- a1\n  1. b1\n- c1\n  - d1\n  - e1\n", "b1", 1, "c1", 1, "- a1\n  1. b{X}1\n  2. d1\n  3. e1\n", "     ", [nil, 0, 0, 0]),
            ("> q1\n\n- a1\n  - c1\n- s1\n", "q1", 1, "a1", 1, "> q{X}1\n\n- c1\n- s1\n", "> ", [nil, nil]),
            ("Before target after\n", "Before target after", 7, "Before target after", 13, "Before {X} after\n", "", [])
