                func breaks(_ node: any Markup) -> Int { (node is LineBreak || (node as? InlineHTML)?.rawHTML == "<br>" ? 1 : 0) + node.children.reduce(0) { $0 + breaks($1) } }
                XCTAssertEqual(breaks(Document(parsing: state.text)), multiline ? 1 : 0)
                XCTAssertEqual(MacMarkdown.render(state.text).string.replacingOccurrences(of: "\u{2028}", with: "\n"), view.string.replacingOccurrences(of: "\u{2028}", with: "\n"), "Reopening must keep the visible pasted lines and item text")
