                }
                let savedAssets = try assetState()
                let html = "<p><img alt='Refused' src='data:image/png;base64," + self.png.base64EncodedString() + "'></p>"
                let multilineHTML = "<p><img alt='Refused' src='data:image/png;base64," + self.png.base64EncodedString() + "'><br>X</p>"
                let paragraphsHTML = html + "<p>Later paragraph</p>"
                let blocksHTML = "<ul><li><img alt='Refused' src='data:image/png;base64," + self.png.base64EncodedString() + "'></li><li>X</li></ul>"
                let blockIssue = "This paste needs Markdown source editing to preserve its block boundaries."
                let selectionIssue = "This list needs Markdown source editing before this selection can preserve its item relationships."
                let paragraphIssue = "This paste needs Markdown source editing to preserve its paragraph boundaries."
                let attempts: [(MacClipboard.Payload, Int, String)] = [(.plain("X"), 1, selectionIssue), (.fragment(.init(markdown: "**X**")), 1, selectionIssue), (.html(Data(html.utf8)), 2, selectionIssue), (.plain("X\nY"), 1, selectionIssue), (.fragment(.init(markdown: "**X**  \n**Y**")), 1, selectionIssue), (.html(Data(multilineHTML.utf8)), 2, selectionIssue), (.html(Data(paragraphsHTML.utf8)), 2, paragraphIssue), (.html(Data(blocksHTML.utf8)), 2, blockIssue)]
                let caretAttempts: [(MacClipboard.Payload, Int, String)] = [(.plain("X\nY"), 1, selectionIssue), (.fragment(.init(markdown: "**X**  \n**Y**")), 1, selectionIssue), (.html(Data(multilineHTML.utf8)), 2, selectionIssue), (.html(Data(paragraphsHTML.utf8)), 2, paragraphIssue), (.html(Data(blocksHTML.utf8)), 2, blockIssue)]
                for (selection, trials) in [(selection, attempts), (NSRange(location: parent.location + 3, length: 0), caretAttempts)] {
