                    catch { XCTAssertEqual(error.localizedDescription, expectedIssue) }
                    XCTAssertEqual(state.text, before); XCTAssertEqual(MacMarkdown.markdown(view.attributedString()), before)
                    XCTAssertEqual(view.string, visible); XCTAssertEqual(view.selectedRange(), selection); XCTAssertTrue(view.isEditable)
                    XCTAssertEqual(view.undoManager?.undoActionName, undoName)
                    XCTAssertEqual(try assetState(), savedAssets, "Refusing or retrying an image paste must not write orphan assets")
                } } }
                coordinator.action("undo"); XCTAssertEqual(state.text, refusedSource, "Refusal must not add an Undo entry")
                coordinator.action("redo"); XCTAssertEqual(state.text, before)
