    func testSpreadsheetPasteExpandsFromTheActiveCellAndUndoRestoresTheOriginalGrid() async throws {
        try await systemClipboard { board in
            let original = "# Grid\n\n<!-- zerus-table-widths: 200,160 -->\n| Name | Value |\n| :--- | ---: |\n| Keep | target |\n\nAfter _spelling_.\n"
            try await self.editor(original, root: true) { view, coordinator, state, _ in
                view.setSelectedRange((view.string as NSString).range(of: "target"))
                board.clearContents(); board.setString("*literal*\t42\r\n\"line 1\nline 2\"\t\"Café \"\"quoted\"\"\"\r\n", forType: .string)
                try await coordinator.paste(try XCTUnwrap(MacClipboard.payload(board, plain: false)))
                let expected = "# Grid\n\n<!-- zerus-table-widths: 200,160,160 -->\n| Name | Value |  |\n| :--- | ---: | --- |\n| Keep | \\*literal\\* | 42 |\n|  | line 1<br>line 2 | Café \"quoted\" |\n\nAfter _spelling_.\n"
                XCTAssertEqual(state.text, expected); XCTAssertFalse(state.source)
                coordinator.action("undo"); XCTAssertEqual(state.text, original)
                coordinator.action("redo"); XCTAssertEqual(state.text, expected)
                coordinator.action("undo")
                view.setSelectedRange((view.string as NSString).range(of: "target"))
                board.clearContents(); board.setString("Single\nColumn\n", forType: .tabularText)
                try await coordinator.paste(try XCTUnwrap(MacClipboard.payload(board, plain: false)))
                XCTAssertTrue(state.text.contains("| Keep | Single |\n|  | Column |"), state.text)
                coordinator.action("undo"); XCTAssertEqual(state.text, original)
            }
        }
    }
    func testNativeTableRowCopyPublishesTSVAndPortableMarkdownAndCutKeepsTheGrid() async throws {
        try await systemClipboard { board in
            let original = "| H1 | H2 |\n| --- | --- |\n| **Alpha** | Beta<br>tail |\n"
            try await self.editor(original, root: true) { view, coordinator, state, _ in
                let first = (view.string as NSString).range(of: "Alpha"), last = (view.string as NSString).range(of: "tail")
                view.setSelectedRange(NSRange(location: first.location, length: NSMaxRange(last) - first.location))
                try await coordinator.copy(cut: true)
                XCTAssertEqual(board.string(forType: .tabularText), "Alpha\t\"Beta\ntail\"")
                XCTAssertEqual(board.string(forType: .string), "Alpha\t\"Beta\ntail\"")
                let fragment = try NativeClipboardFragment.decode(try XCTUnwrap(board.data(forType: .init(NativeClipboardFragment.type))))
                XCTAssertEqual(fragment.markdown, "| **Alpha** | Beta<br>tail |\n| --- | --- |")
                XCTAssertEqual(state.text, "| H1 | H2 |\n| --- | --- |\n|  |  |\n")
                coordinator.action("undo"); XCTAssertEqual(state.text, original)
                view.setSelectedRange((view.string as NSString).range(of: "Alpha")); try await coordinator.copy(cut: false)
