    func testExternalProjectImageCopyCarriesOriginalBytesIntoAVault() async throws {
        let folder = FileManager.default.temporaryDirectory.appendingPathComponent("Zerus-external-copy-" + UUID().uuidString)
        try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: folder) }
        let file = folder.appendingPathComponent("External.md"), picture = folder.appendingPathComponent("Photo.png")
        for (body, ending) in [("![External|128](./Photo.png)", "\n"), ("![External|128](./Photo.png) [l](https://e/)", "\r\n")] {
            let markdown = body + ending
            try Data(markdown.utf8).write(to: file); try png.write(to: picture)
            let project = try NativeExternalProjectFiles(selectedProject: folder, source: file)
            try await systemClipboard { board in
                try await self.editor(markdown, root: false) { view, coordinator, _, _ in
                    coordinator.parent.project = project
                    view.setSelectedRange(NSRange(location: 0, length: view.string.utf16.count - 1)); try await coordinator.copy(cut: false)
                    let fragment = try NativeClipboardFragment.decode(try XCTUnwrap(board.data(forType: .init(NativeClipboardFragment.type))))
                    XCTAssertEqual(fragment.markdown, body, "Body-only copy keeps the image/link spelling and excludes its line ending")
                    XCTAssertEqual(fragment.resources.first?.bytes, self.png); XCTAssertTrue(fragment.markdown.contains("External|128"))
                    XCTAssertNotNil(board.data(forType: .rtfd))
                }
                try await self.editor("# Destination\n\n", root: true) { view, coordinator, state, root in
                    view.setSelectedRange(NSRange(location: view.string.utf16.count, length: 0))
                    try await coordinator.paste(try XCTUnwrap(MacClipboard.payload(board, plain: false)))
                    let reference = try XCTUnwrap(MarkdownText.imageReferences(state.text).first)
                    let imported = try VaultFiles.resolveResource(reference, notePath: "Work/Paste.md", root: XCTUnwrap(root))
                    XCTAssertEqual(try Data(contentsOf: imported), self.png); XCTAssertTrue(state.text.contains("External|128"))
                    if body.contains("https://e/") { XCTAssertTrue(state.text.contains("[l](https://e/)")) }
                    coordinator.action("undo"); XCTAssertEqual(state.text, "# Destination\n\n")
                }
            }
            XCTAssertEqual(try Data(contentsOf: picture), png); XCTAssertEqual(try String(contentsOf: file, encoding: .utf8), markdown)
        }
    }

