    func testRichCodeCopiesAcrossNotesAndPasteWithinItsBodyStaysLiteral() async throws {
        let defaults = UserDefaults.standard, key = "zerus.mac.codeBlocks", previous = defaults.object(forKey: key)
        defer { if let previous { defaults.set(previous, forKey: key) } else { defaults.removeObject(forKey: key) } }
        defaults.set(true, forKey: key)
        try await systemClipboard { board in
            let code = "~~~swift extra\nlet message = \"**literal**\"\n~~~\n"
            try await self.editor("# Source\n\n" + code, root: true) { view, coordinator, _, _ in
                var range = NSRange()
                let start = (view.string as NSString).range(of: "let message").location
                _ = view.attributedString().attribute(.macCode, at: start, longestEffectiveRange: &range, in: NSRange(location: 0, length: view.string.utf16.count))
                view.setSelectedRange(range); try await coordinator.copy(cut: false)
                let payload = try XCTUnwrap(MacClipboard.payload(board, plain: false))
                try await self.editor("Before target after.", root: true) { target, destination, state, _ in
                    target.setSelectedRange((target.string as NSString).range(of: "target")); try await destination.paste(payload)
                    XCTAssertEqual(FencedCode.blocks(in: state.text).first?.code.body, "let message = \"**literal**\"")
                    XCTAssertTrue(state.text.hasPrefix("Before&#32;\n\n")); XCTAssertTrue(state.text.hasSuffix("\n\n&#32;after.")); XCTAssertFalse(state.source)
                    XCTAssertEqual(MacMarkdown.render(state.text).string, target.string)
                    let copied = state.text
                    target.setSelectedRange((target.string as NSString).range(of: "**literal**"))
                    try await destination.paste(.plain("**still literal** @Cafe\n- item"))
                    XCTAssertTrue(FencedCode.blocks(in: state.text).first?.code.body.contains("**still literal** @Cafe\n- item") == true)
                    destination.action("undo"); XCTAssertEqual(state.text, copied)
                    destination.action("redo"); XCTAssertTrue(target.string.contains("**still literal** @Cafe")); XCTAssertFalse(state.source)
                    destination.action("undo")
                    let payloads: [MacClipboard.Payload] = [.html(Data("<strong>X</strong><br>Y".utf8)), .fragment(.init(markdown: "**X**<br>Y"))]
                    for payload in payloads {
                        target.setSelectedRange((target.string as NSString).range(of: "**literal**"))
                        try await destination.paste(payload)
                        XCTAssertEqual(FencedCode.blocks(in: state.text).first?.code.body, "let message = \"X\nY\"")
                        destination.action("undo"); XCTAssertEqual(state.text, copied)
                    }
                }
            }
        }
    }
