    func testRTFDTransportKeepsBoldLinkAndEmbeddedImageWhilePlainPasteRemainsLiteral() async throws {
        let rich = NSMutableAttributedString(string: "Bold link\n", attributes: [.font: NSFont.systemFont(ofSize: 15)])
        rich.addAttribute(.font, value: NSFont.boldSystemFont(ofSize: 15), range: NSRange(location: 0, length: 4))
        rich.addAttribute(.link, value: URL(string: "https://example.com/path")!, range: NSRange(location: 5, length: 4))
        let attachment = NSTextAttachment(); attachment.image = NSImage(data: png)
        rich.append(NSAttributedString(attachment: attachment))
        let bytes = try rich.data(from: NSRange(location: 0, length: rich.length), documentAttributes: [.documentType: NSAttributedString.DocumentType.rtfd])
        let board = NSPasteboard.withUniqueName(); defer { board.releaseGlobally() }
        board.setData(bytes, forType: .rtfd); board.setString("# Literal text", forType: .string)
        let payload = try XCTUnwrap(MacClipboard.payload(board, plain: false))
        try await editor("", root: true) { _, coordinator, state, root in
            try await coordinator.paste(payload)
            XCTAssertTrue(state.text.contains("**Bold**")); XCTAssertTrue(state.text.contains("[link](https://example.com/path)"))
            let reference = try XCTUnwrap(MarkdownText.imageReferences(state.text).first)
            let file = try VaultFiles.resolveResource(reference, notePath: "Work/Paste.md", root: try XCTUnwrap(root))
            XCTAssertNotNil(NSImage(contentsOf: file)); XCTAssertFalse(state.text.contains("\u{fffc}"))
        }
        let decoded = try NSAttributedString(data: bytes, options: [.documentType: NSAttributedString.DocumentType.rtfd], documentAttributes: nil)
        let companion = try XCTUnwrap(MacClipboard.rich(decoded).resources.first)
        board.setString("<p><strong>Bold</strong> <a href='https://example.com/path'>link</a></p><img src='cid:" + companion.name + "'>", forType: .html)
        let mixed = try XCTUnwrap(MacClipboard.payload(board, plain: false))
        try await editor("", root: true) { _, coordinator, state, root in
            try await coordinator.paste(mixed)
            let reference = try XCTUnwrap(MarkdownText.imageReferences(state.text).first)
            let file = try VaultFiles.resolveResource(reference, notePath: "Work/Paste.md", root: try XCTUnwrap(root))
            XCTAssertEqual(try Data(contentsOf: file), companion.bytes)
            XCTAssertTrue(state.text.contains("**Bold**"))
        }
        let plain = try XCTUnwrap(MacClipboard.payload(board, plain: true))
        try await editor("", root: false) { _, coordinator, state, _ in
            try await coordinator.paste(plain)
            XCTAssertTrue(state.text.hasPrefix("\\# Literal text")); XCTAssertFalse(state.source)
        }
        for separator in ["\n", "\r\n", "\r", "\u{2029}"] {
            let passage = NSAttributedString(string: "First" + separator + "Second\u{2028}line" + separator + "Third" + separator,
                                             attributes: [.font: NSFont.systemFont(ofSize: 15)])
            let encoded = try passage.data(from: NSRange(location: 0, length: passage.length), documentAttributes: [.documentType: NSAttributedString.DocumentType.rtfd])
            board.clearContents(); board.setData(encoded, forType: .rtfd)
            let payload = try XCTUnwrap(MacClipboard.payload(board, plain: false))
            try await editor("", root: true) { _, coordinator, state, _ in
                try await coordinator.paste(payload)
                let paragraphs = Document(parsing: state.text).children.compactMap { $0 as? Paragraph }
                XCTAssertEqual(paragraphs.map(\.plainText), ["First", "Second\nline", "Third"], "Rich paragraphs stay separate; a line separator stays within its paragraph")
                XCTAssertFalse(state.source)
                let pasted = state.text
                coordinator.action("undo"); XCTAssertEqual(state.text, "")
                coordinator.action("redo"); XCTAssertEqual(state.text, pasted)
                XCTAssertEqual(Document(parsing: MacMarkdown.markdown(MacMarkdown.render(state.text))).children.compactMap { $0 as? Paragraph }.map(\.plainText), ["First", "Second\nline", "Third"])
            }
        }
    }
