                let fragment = try NativeClipboardFragment.decode(try XCTUnwrap(board.data(forType: .init(NativeClipboardFragment.type))))
                XCTAssertEqual(fragment.markdown, copied); XCTAssertTrue(fragment.resources.isEmpty)
                XCTAssertEqual(MacMarkdown.markdown(view.attributedString()), source, "Copy must leave the original attributed document untouched")
                let rich = try NSAttributedString(data: try XCTUnwrap(board.data(forType: .rtfd)), options: [.documentType: NSAttributedString.DocumentType.rtfd], documentAttributes: nil)
                XCTAssertEqual(rich.string, selected)
