                            receiver.action("redo"); XCTAssertEqual(state.text, expected)
                        }
                    }
                }
            }
            }
        }
    }
    // Exercise the real AppKit clipboard boundary without adding a production
    // injection seam; restore every available representation without logging it.
    private func systemClipboard(_ operation: (NSPasteboard) async throws -> Void) async throws {
        let board = NSPasteboard.general
        let saved = (board.pasteboardItems ?? []).map { old -> NSPasteboardItem in
            let item = NSPasteboardItem(); for type in old.types { if let data = old.data(forType: type) { item.setData(data, forType: type) } }; return item
        }
        defer { board.clearContents(); if !saved.isEmpty { board.writeObjects(saved) } }
        try await operation(board)
    }
    func testAttachmentChooserCommandKeepsEarlierEditsAndSupportsOneUndoRedo() async throws {
        for sourceMode in [false, true] {
            try await editor("Keep this spelling.\n", root: true, sourceMode: sourceMode) { view, coordinator, state, root in
                let root = try XCTUnwrap(root), scope = UUID()
                coordinator.parent.commandScope = scope
                let word = (view.string as NSString).range(of: "Keep")
                view.setSelectedRange(word); view.insertText("Retain", replacementRange: word)
                let before = "Retain this spelling.\n"
                XCTAssertEqual(state.text, before)
                let fragment = NativeClipboardFragment(markdown: "\n![Diagram](assets/import.png)\n", resources: [.init(reference: "assets/import.png", path: nil, name: "import.png", bytes: self.png)])
                let command = MacAttachmentImport(scope: scope, path: "Work/Paste.md", source: before, fragment: fragment)
                NotificationCenter.default.post(name: .macEditorAction, object: command)
                try await XCTUnwrap(command.task).value
                let inserted = state.text
                XCTAssertTrue(inserted.contains("![Diagram](assets/"), inserted)
                let reference = try XCTUnwrap(MarkdownText.imageReferences(inserted).first)
                let file = try VaultFiles.resolveResource(reference, notePath: "Work/Paste.md", root: root)
                XCTAssertEqual(try Data(contentsOf: file), self.png)
                coordinator.action("undo"); XCTAssertEqual(state.text, before, "One Undo must remove the imported attachment without losing earlier edits")
                coordinator.action("redo"); XCTAssertEqual(state.text, inserted)
                XCTAssertEqual(try Data(contentsOf: file), self.png, "Redo and saved recovery references must retain the imported bytes")
                let stale = MacAttachmentImport(scope: scope, path: "Work/Paste.md", source: before, fragment: fragment)
                let files = try FileManager.default.contentsOfDirectory(atPath: root.appendingPathComponent("assets").path)
                NotificationCenter.default.post(name: .macEditorAction, object: stale)
                do { try await XCTUnwrap(stale.task).value; XCTFail("A stale chooser result must not import another file") }
                catch { XCTAssertTrue(error.localizedDescription.contains("note changed"), error.localizedDescription) }
                XCTAssertEqual(state.text, inserted)
                XCTAssertEqual(try FileManager.default.contentsOfDirectory(atPath: root.appendingPathComponent("assets").path), files)
            }
        }
    }
    func testRepeatedCrossVaultCopiesKeepImageNamesWithinFilesystemLimits() async throws {
        let base = FileManager.default.temporaryDirectory.appendingPathComponent("Zerus-repeated-clipboard-" + UUID().uuidString)
        let a = base.appendingPathComponent("A"), b = base.appendingPathComponent("B")
        try FileManager.default.createDirectory(at: a.appendingPathComponent("assets"), withIntermediateDirectories: true); try FileManager.default.createDirectory(at: b, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: base) }
        let name = String(repeating: "Café", count: 20) + ".png"
        try png.write(to: a.appendingPathComponent("assets/" + name))
        let first = VaultFiles(root: a), second = VaultFiles(root: b)
        var markdown = "![Kept image](assets/" + name.addingPercentEncoding(withAllowedCharacters: .urlPathAllowed)! + ")"
        for iteration in 0..<10 {
            let source = iteration.isMultiple(of: 2) ? first : second, target = iteration.isMultiple(of: 2) ? second : first
            let targetRoot = iteration.isMultiple(of: 2) ? b : a
            let fragment = try await source.clipboardFragment(markdown, notePath: "Note.md")
            markdown = try await target.importClipboard(fragment)
            let reference = try XCTUnwrap(MarkdownText.imageReferences(markdown).first), file = try VaultFiles.resolveResource(reference, notePath: "Note.md", root: targetRoot)
            XCTAssertEqual(try Data(contentsOf: file), png)
            XCTAssertEqual(file.pathExtension, "png"); XCTAssertLessThanOrEqual(file.lastPathComponent.decomposedStringWithCanonicalMapping.utf8.count, 255)
            XCTAssertTrue(markdown.hasPrefix("![Kept image]"))
        }
    }
    private final class State { var text: String; var source = false; var document: NoteDocument; init(_ text: String, header: String) { self.text = text; document = .init(path: "External.md", content: header + text, modified: Date()) } }
    private func editor(_ text: String, root usesRoot: Bool, header: String = "", sourceMode: Bool = false, operation: (NSTextView, MacRichEditor.Coordinator, State, URL?) async throws -> Void) async throws {
        let root = usesRoot ? FileManager.default.temporaryDirectory.appendingPathComponent("Zerus-paste-" + UUID().uuidString) : nil
        if let root { try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true) }
        defer { if let root { try? FileManager.default.removeItem(at: root) } }
        let state = State(text, header: header); state.source = sourceMode
        let parent = MacRichEditor(markdown: text, source: sourceMode, editable: true, root: root, path: "Work/Paste.md", onChange: { state.text = $0 }, onLink: { _ in }, onSourceChange: { state.source = $0 }, sourceHeader: header, onModeChange: { value, full in state.text = value; state.document.content = full ? value : state.document.replacingBody(value) })
        let coordinator = MacRichEditor.Coordinator(parent), view = NSTextView()
        view.isRichText = true; view.allowsUndo = true; view.delegate = coordinator; coordinator.view = view
        let window = NSWindow(contentRect: NSRect(x: 0, y: 0, width: 600, height: 500), styleMask: .borderless, backing: .buffered, defer: false)
        window.isReleasedWhenClosed = false; window.contentView = view; window.makeFirstResponder(view)
        defer { coordinator.detach(); window.close() }
        coordinator.load(text, source: sourceMode)
        try await operation(view, coordinator, state, root)
    }
